30	  incident: Incident;
31	}
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	export interface Scenario {
36	  customer: Customer;
37	  steps: Step[];
38	}
39	
40	export interface QuoteResult {
41	  premium: number;
42	}
43	
44	export interface ClaimResult {
45	  payout: number;
46	  remainingCap: number;
47	}
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export interface ScenarioResult {
52	  results: StepResult[];
53	}
54	
55	const PROCESSING_FEE = 5;
56	const INITIAL_ASSESSMENT_SURCHARGE_RATE = 0.1;
57	
58	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
59	  sword: 100,
60	  amulet: 60,
61	  staff: 80,
62	  potion: 40,
63	};
64	
65	/** Rounds to whole G in the MHPCO's favour. */
66	const roundUpToWholeG = (amount: number): number => Math.ceil(amount);
67	
68	const quotePremium = (items: Item[]): number => {
69	  const policyBasePremium = items.reduce((sum, item) => sum + BASE_PREMIUM_BY_TYPE[item.type], 0);
70	  const initialAssessmentSurcharge = policyBasePremium * INITIAL_ASSESSMENT_SURCHARGE_RATE;
71	  return roundUpToWholeG(policyBasePremium + initialAssessmentSurcharge + PROCESSING_FEE);
72	};
73	
74	export const runScenario = (scenario: Scenario): ScenarioResult => {
75	  return {
76	    results: scenario.steps.map((step) => ({
77	      premium: quotePremium((step as QuoteStep).items),
78	    })),
79	  };
80	};
